import{_ as o,c as t,o as a,aj as s}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: DocumentIngestSession","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentIngestSession.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentIngestSession.md"}'),c={name:"reference/js-bao-wss-client/api/interfaces/DocumentIngestSession.md"};function r(d,e,n,i,l,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentIngestSession</p><h1 id="interface-documentingestsession" tabindex="-1">Interface: DocumentIngestSession <a class="header-anchor" href="#interface-documentingestsession" aria-label="Permalink to “Interface: DocumentIngestSession”">​</a></h1><p>One bulk-load session, as the server describes it.</p><p>A session is how a directory of records becomes a large document&#39;s table: it is created, its chunks are uploaded, it is committed, and the pipeline then copies, applies, reconciles and swaps on the room&#39;s alarm. Nothing here is a key, a signature or a cursor — the view is what an operator may see.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="buildid" tabindex="-1">buildId <a class="header-anchor" href="#buildid" aria-label="Permalink to “buildId”">​</a></h3><blockquote><p><strong>buildId</strong>: <code>string</code> | <code>null</code></p></blockquote><p>The base build the session waits on before it reports <code>complete</code>.</p><hr><h3 id="bytes" tabindex="-1">bytes <a class="header-anchor" href="#bytes" aria-label="Permalink to “bytes”">​</a></h3><blockquote><p><strong>bytes</strong>: <code>number</code></p></blockquote><hr><h3 id="chunks" tabindex="-1">chunks <a class="header-anchor" href="#chunks" aria-label="Permalink to “chunks”">​</a></h3><blockquote><p><strong>chunks</strong>: <code>number</code></p></blockquote><p>How many chunks the committed manifest holds.</p><hr><h3 id="completedat" tabindex="-1">completedAt? <a class="header-anchor" href="#completedat" aria-label="Permalink to “completedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>completedAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="copystartedat" tabindex="-1">copyStartedAt? <a class="header-anchor" href="#copystartedat" aria-label="Permalink to “copyStartedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>copyStartedAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="createdat" tabindex="-1">createdAt? <a class="header-anchor" href="#createdat" aria-label="Permalink to “createdAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>createdAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="createdby" tabindex="-1">createdBy? <a class="header-anchor" href="#createdby" aria-label="Permalink to “createdBy?”">​</a></h3><blockquote><p><code>optional</code> <strong>createdBy?</strong>: <code>string</code></p></blockquote><hr><h3 id="discontinuityepoch" tabindex="-1">discontinuityEpoch <a class="header-anchor" href="#discontinuityepoch" aria-label="Permalink to “discontinuityEpoch”">​</a></h3><blockquote><p><strong>discontinuityEpoch</strong>: <code>number</code> | <code>null</code></p></blockquote><p>The epoch the swap sealed with a base discontinuity, once it has happened. Connected clients converge on the base built for the epoch after it.</p><hr><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><hr><h3 id="expiresat" tabindex="-1">expiresAt? <a class="header-anchor" href="#expiresat" aria-label="Permalink to “expiresAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>expiresAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><hr><h3 id="failure" tabindex="-1">failure <a class="header-anchor" href="#failure" aria-label="Permalink to “failure”">​</a></h3><blockquote><p><strong>failure</strong>: { <code>code</code>: <code>string</code>; <code>reason</code>: <code>string</code>; <code>rows?</code>: <code>object</code>[]; } | <code>null</code></p></blockquote><p>Why a <code>failed</code> session failed, with the rows that caused it.</p><h4 id="union-members" tabindex="-1">Union Members <a class="header-anchor" href="#union-members" aria-label="Permalink to “Union Members”">​</a></h4><h5 id="type-literal" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>code</code>: <code>string</code>; <code>reason</code>: <code>string</code>; <code>rows?</code>: <code>object</code>[]; }</p><h5 id="code" tabindex="-1">code <a class="header-anchor" href="#code" aria-label="Permalink to “code”">​</a></h5><blockquote><p><strong>code</strong>: <code>string</code></p></blockquote><h5 id="reason" tabindex="-1">reason <a class="header-anchor" href="#reason" aria-label="Permalink to “reason”">​</a></h5><blockquote><p><strong>reason</strong>: <code>string</code></p></blockquote><h5 id="rows" tabindex="-1">rows? <a class="header-anchor" href="#rows" aria-label="Permalink to “rows?”">​</a></h5><blockquote><p><code>optional</code> <strong>rows?</strong>: <code>object</code>[]</p></blockquote><p>The records the failure names, each as its model and its id.</p><hr><p><code>null</code></p><hr><h3 id="progress" tabindex="-1">progress <a class="header-anchor" href="#progress" aria-label="Permalink to “progress”">​</a></h3><blockquote><p><strong>progress</strong>: <code>object</code></p></blockquote><h4 id="chunksapplied" tabindex="-1">chunksApplied <a class="header-anchor" href="#chunksapplied" aria-label="Permalink to “chunksApplied”">​</a></h4><blockquote><p><strong>chunksApplied</strong>: <code>number</code></p></blockquote><h4 id="oldrowsremoved" tabindex="-1">oldRowsRemoved <a class="header-anchor" href="#oldrowsremoved" aria-label="Permalink to “oldRowsRemoved”">​</a></h4><blockquote><p><strong>oldRowsRemoved</strong>: <code>number</code></p></blockquote><p>Rows taken off the tables a swap moved aside, monotonic.</p><p>The number that says whether a session in <code>registering</code> is advancing. Removal is bounded per tick, so a large document leaves the state over many alarms and this climbs across them.</p><h4 id="recordsreconciled" tabindex="-1">recordsReconciled <a class="header-anchor" href="#recordsreconciled" aria-label="Permalink to “recordsReconciled”">​</a></h4><blockquote><p><strong>recordsReconciled</strong>: <code>number</code></p></blockquote><h4 id="rowsapplied" tabindex="-1">rowsApplied <a class="header-anchor" href="#rowsapplied" aria-label="Permalink to “rowsApplied”">​</a></h4><blockquote><p><strong>rowsApplied</strong>: <code>number</code></p></blockquote><h4 id="rowscopied" tabindex="-1">rowsCopied <a class="header-anchor" href="#rowscopied" aria-label="Permalink to “rowsCopied”">​</a></h4><blockquote><p><strong>rowsCopied</strong>: <code>number</code></p></blockquote><hr><h3 id="rawbytes" tabindex="-1">rawBytes? <a class="header-anchor" href="#rawbytes" aria-label="Permalink to “rawBytes?”">​</a></h3><blockquote><p><code>optional</code> <strong>rawBytes?</strong>: <code>number</code> | <code>null</code></p></blockquote><p>Decompressed bytes across the stored chunks.</p><p><code>null</code> when it cannot be known: a session that completed before timings were recorded has had its chunk descriptors swept with its reservations.</p><hr><h3 id="rows-1" tabindex="-1">rows <a class="header-anchor" href="#rows-1" aria-label="Permalink to “rows”">​</a></h3><blockquote><p><strong>rows</strong>: <code>number</code></p></blockquote><hr><h3 id="sessionid" tabindex="-1">sessionId <a class="header-anchor" href="#sessionid" aria-label="Permalink to “sessionId”">​</a></h3><blockquote><p><strong>sessionId</strong>: <code>string</code></p></blockquote><hr><h3 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h3><blockquote><p><strong>state</strong>: <code>&quot;uploading&quot;</code> | <code>&quot;failed&quot;</code> | <code>&quot;committed&quot;</code> | <code>&quot;validating&quot;</code> | <code>&quot;staging&quot;</code> | <code>&quot;applying&quot;</code> | <code>&quot;finalizing&quot;</code> | <code>&quot;registering&quot;</code> | <code>&quot;complete&quot;</code> | <code>&quot;aborted&quot;</code></p></blockquote><p>Where the session is. <code>uploading</code> accepts chunks; <code>committed</code> has frozen its manifest; the four working states are the pipeline&#39;s own; <code>complete</code> means the ingested table is live and its base is verified.</p><hr><h3 id="stateenteredat" tabindex="-1">stateEnteredAt? <a class="header-anchor" href="#stateenteredat" aria-label="Permalink to “stateEnteredAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>stateEnteredAt?</strong>: <code>string</code> | <code>null</code></p></blockquote><p>When the current state began.</p><hr><h3 id="throughput" tabindex="-1">throughput? <a class="header-anchor" href="#throughput" aria-label="Permalink to “throughput?”">​</a></h3><blockquote><p><code>optional</code> <strong>throughput?</strong>: { <code>pipelineMs</code>: <code>number</code>; <code>rawBytesPerSecond</code>: <code>number</code> | <code>null</code>; <code>rowsPerSecond</code>: <code>number</code>; <code>storedBytesPerSecond</code>: <code>number</code>; } | <code>null</code></p></blockquote><p>Rates over the pipeline window, <code>committed</code> through the swap.</p><p><code>null</code> unless the session reached <code>registering</code> and its timing history begins at <code>uploading</code>: a window nobody measured gets no rate rather than an invented one.</p><h4 id="union-members-1" tabindex="-1">Union Members <a class="header-anchor" href="#union-members-1" aria-label="Permalink to “Union Members”">​</a></h4><h5 id="type-literal-1" tabindex="-1">Type Literal <a class="header-anchor" href="#type-literal-1" aria-label="Permalink to “Type Literal”">​</a></h5><p>{ <code>pipelineMs</code>: <code>number</code>; <code>rawBytesPerSecond</code>: <code>number</code> | <code>null</code>; <code>rowsPerSecond</code>: <code>number</code>; <code>storedBytesPerSecond</code>: <code>number</code>; }</p><h5 id="pipelinems" tabindex="-1">pipelineMs <a class="header-anchor" href="#pipelinems" aria-label="Permalink to “pipelineMs”">​</a></h5><blockquote><p><strong>pipelineMs</strong>: <code>number</code></p></blockquote><h5 id="rawbytespersecond" tabindex="-1">rawBytesPerSecond <a class="header-anchor" href="#rawbytespersecond" aria-label="Permalink to “rawBytesPerSecond”">​</a></h5><blockquote><p><strong>rawBytesPerSecond</strong>: <code>number</code> | <code>null</code></p></blockquote><p><code>null</code> when the decompressed total is unknown.</p><h5 id="rowspersecond" tabindex="-1">rowsPerSecond <a class="header-anchor" href="#rowspersecond" aria-label="Permalink to “rowsPerSecond”">​</a></h5><blockquote><p><strong>rowsPerSecond</strong>: <code>number</code></p></blockquote><h5 id="storedbytespersecond" tabindex="-1">storedBytesPerSecond <a class="header-anchor" href="#storedbytespersecond" aria-label="Permalink to “storedBytesPerSecond”">​</a></h5><blockquote><p><strong>storedBytesPerSecond</strong>: <code>number</code></p></blockquote><hr><p><code>null</code></p><hr><h3 id="timings" tabindex="-1">timings? <a class="header-anchor" href="#timings" aria-label="Permalink to “timings?”">​</a></h3><blockquote><p><code>optional</code> <strong>timings?</strong>: <code>object</code></p></blockquote><p>Where the session&#39;s time went.</p><p>Three kinds of number, and they are not equally exact. A STATE WINDOW and an INTERVAL are wall time between tick starts, and every tick starts in a fresh alarm invocation, so both are exact. A STAGE total is what the tick&#39;s own timers read, and on Workers the clock advances only across I/O: <code>copyMs</code>, <code>applyMs</code>, <code>decodeMs</code>, <code>swapMs</code> and <code>registerMs</code> read 0 there, while <code>readMs</code>, <code>sealMs</code> and <code>manifestMs</code> are observation intervals ending at an I/O boundary that include the synchronous work before them. <code>intervalMs</code> belongs to the tick that STARTED it and includes the room&#39;s post-tick work and the 1,000 ms re-arm delay.</p><p>A server that settles the clock brackets those stage timers, and <code>totals.bracketedTicks</code> says how many ticks it managed it for. A bracketed stage total is WALL milliseconds — it includes the settle&#39;s own cost and any I/O inside the bracket — and is not CPU time. The ledger clock still does not move inside a transaction, so an unbracketed tick reads 0 for every synchronous stage. <code>totals.counters</code> is the clock-free half and is exact wherever the host has cursor counters.</p><p>Optional, because an older server omits the whole block.</p><h4 id="longestinterval" tabindex="-1">longestInterval <a class="header-anchor" href="#longestinterval" aria-label="Permalink to “longestInterval”">​</a></h4><blockquote><p><strong>longestInterval</strong>: { <code>intervalMs</code>: <code>number</code>; <code>state</code>: <code>&quot;uploading&quot;</code> | <code>&quot;failed&quot;</code> | <code>&quot;committed&quot;</code> | <code>&quot;validating&quot;</code> | <code>&quot;staging&quot;</code> | <code>&quot;applying&quot;</code> | <code>&quot;finalizing&quot;</code> | <code>&quot;registering&quot;</code> | <code>&quot;complete&quot;</code> | <code>&quot;aborted&quot;</code>; } | <code>null</code></p></blockquote><h4 id="since" tabindex="-1">since <a class="header-anchor" href="#since" aria-label="Permalink to “since”">​</a></h4><blockquote><p><strong>since</strong>: <code>&quot;uploading&quot;</code> | <code>&quot;failed&quot;</code> | <code>&quot;committed&quot;</code> | <code>&quot;validating&quot;</code> | <code>&quot;staging&quot;</code> | <code>&quot;applying&quot;</code> | <code>&quot;finalizing&quot;</code> | <code>&quot;registering&quot;</code> | <code>&quot;complete&quot;</code> | <code>&quot;aborted&quot;</code> | <code>null</code></p></blockquote><p>Where this row&#39;s history begins; <code>uploading</code> for a modern session.</p><h4 id="states" tabindex="-1">states <a class="header-anchor" href="#states" aria-label="Permalink to “states”">​</a></h4><blockquote><p><strong>states</strong>: <code>Partial</code>&lt;<code>Record</code>&lt;<code>DocumentIngestSession</code>[<code>&quot;state&quot;</code>], { <code>intervalMs</code>: <code>number</code>; <code>ms</code>: <code>number</code>; <code>ticks</code>: <code>number</code>; }&gt;&gt;</p></blockquote><h4 id="ticks" tabindex="-1">ticks <a class="header-anchor" href="#ticks" aria-label="Permalink to “ticks”">​</a></h4><blockquote><p><strong>ticks</strong>: <code>number</code></p></blockquote><h4 id="totals" tabindex="-1">totals <a class="header-anchor" href="#totals" aria-label="Permalink to “totals”">​</a></h4><blockquote><p><strong>totals</strong>: <code>object</code></p></blockquote><h5 id="totals-applyms" tabindex="-1">totals.applyMs <a class="header-anchor" href="#totals-applyms" aria-label="Permalink to “totals.applyMs”">​</a></h5><blockquote><p><strong>applyMs</strong>: <code>number</code></p></blockquote><h5 id="totals-bracketedticks" tabindex="-1">totals.bracketedTicks <a class="header-anchor" href="#totals-bracketedticks" aria-label="Permalink to “totals.bracketedTicks”">​</a></h5><blockquote><p><strong>bracketedTicks</strong>: <code>number</code></p></blockquote><p>Ticks whose stage timers were bracketed by a clock settle.</p><p>The server yields at both ends of every stage bracket so the timer reads the wall time of the work it encloses instead of the 0 a frozen Workers clock gives it. Equal to <code>ticks</code> when every tick was bracketed; less when a settle was refused, and then the stage totals above are the old, un-bracketed figures for those ticks.</p><h5 id="totals-copyms" tabindex="-1">totals.copyMs <a class="header-anchor" href="#totals-copyms" aria-label="Permalink to “totals.copyMs”">​</a></h5><blockquote><p><strong>copyMs</strong>: <code>number</code></p></blockquote><h5 id="totals-counters" tabindex="-1">totals.counters <a class="header-anchor" href="#totals-counters" aria-label="Permalink to “totals.counters”">​</a></h5><blockquote><p><strong>counters</strong>: <code>Record</code>&lt;<code>&quot;manifest&quot;</code> | <code>&quot;read&quot;</code> | <code>&quot;decode&quot;</code> | <code>&quot;copy&quot;</code> | <code>&quot;apply&quot;</code> | <code>&quot;reconcile&quot;</code> | <code>&quot;swap&quot;</code> | <code>&quot;seal&quot;</code> | <code>&quot;register&quot;</code>, <a href="./DocumentIngestStageCounters.html"><code>DocumentIngestStageCounters</code></a>&gt;</p></blockquote><p>What each stage&#39;s SQL did, without asking a clock.</p><p><code>statements</code> is exact everywhere. <code>rowsRead</code> and <code>rowsWritten</code> come from the SQL cursor&#39;s own billing counters and are <code>null</code> where the host has none — never a substituted zero. <code>rowsReturned</code> is a third figure: an aggregate returns one row after reading many.</p><p><code>byTarget</code> splits the same figures by the table each statement named (<code>records</code>, <code>members</code>, <code>claims</code>, <code>log</code>, <code>bookkeeping</code>, <code>other</code>), which is what separates the records fold from string-set maintenance from unique claims inside one stage.</p><h5 id="totals-decodems" tabindex="-1">totals.decodeMs <a class="header-anchor" href="#totals-decodems" aria-label="Permalink to “totals.decodeMs”">​</a></h5><blockquote><p><strong>decodeMs</strong>: <code>number</code></p></blockquote><h5 id="totals-manifestms" tabindex="-1">totals.manifestMs <a class="header-anchor" href="#totals-manifestms" aria-label="Permalink to “totals.manifestMs”">​</a></h5><blockquote><p><strong>manifestMs</strong>: <code>number</code></p></blockquote><h5 id="totals-readms" tabindex="-1">totals.readMs <a class="header-anchor" href="#totals-readms" aria-label="Permalink to “totals.readMs”">​</a></h5><blockquote><p><strong>readMs</strong>: <code>number</code></p></blockquote><h5 id="totals-reconcilems" tabindex="-1">totals.reconcileMs <a class="header-anchor" href="#totals-reconcilems" aria-label="Permalink to “totals.reconcileMs”">​</a></h5><blockquote><p><strong>reconcileMs</strong>: <code>number</code></p></blockquote><h5 id="totals-registerms" tabindex="-1">totals.registerMs <a class="header-anchor" href="#totals-registerms" aria-label="Permalink to “totals.registerMs”">​</a></h5><blockquote><p><strong>registerMs</strong>: <code>number</code></p></blockquote><h5 id="totals-sealms" tabindex="-1">totals.sealMs <a class="header-anchor" href="#totals-sealms" aria-label="Permalink to “totals.sealMs”">​</a></h5><blockquote><p><strong>sealMs</strong>: <code>number</code></p></blockquote><h5 id="totals-swapms" tabindex="-1">totals.swapMs <a class="header-anchor" href="#totals-swapms" aria-label="Permalink to “totals.swapMs”">​</a></h5><blockquote><p><strong>swapMs</strong>: <code>number</code></p></blockquote><h5 id="totals-totalms" tabindex="-1">totals.totalMs <a class="header-anchor" href="#totals-totalms" aria-label="Permalink to “totals.totalMs”">​</a></h5><blockquote><p><strong>totalMs</strong>: <code>number</code></p></blockquote><p>A lower bound on Workers, where a pure-SQL tick reads 0.</p><hr><h3 id="updatedat" tabindex="-1">updatedAt? <a class="header-anchor" href="#updatedat" aria-label="Permalink to “updatedAt?”">​</a></h3><blockquote><p><code>optional</code> <strong>updatedAt?</strong>: <code>string</code> | <code>null</code></p></blockquote>',159)])])}const b=o(c,[["render",r]]);export{p as __pageData,b as default};
